@Override
	protected float modifyAppliedDamage(DamageSource source, float amount) {
		float damage = super.modifyAppliedDamage(source, amount);
		damageTaken += damage;
		fleeDistance = 6;
		fleeingTicks = 0;
		if (damageTaken >= DAMAGE_THRESHOLD) {
			startFleeing();
		}
		return damage;
	}

